/// <summary>
/// Data contract class for sales picking list generation service
/// </summary>
[DataContractAttribute]
class METSalesPickingListGenerationContract
{
    container       salesOrderList;
    //CB123 SalesOrderExtractScreenforCSD -start
    container       csdSalesOrderList;
    //CB123 SalesOrderExtractScreenforCSD -end
    RefRecId        batchJobId;
    boolean         canContinueFromStagingLane;

}

Method.Source:
    /// <summary>
    /// parm method for sales order list container which contains sales order and OSCCode list
    /// </summary>
    /// <param name = "_salesOrderList">sales order list</param>
    /// <returns>sales order list</returns>
    [DataMemberAttribute, SysOperationControlVisibilityAttribute(false)]
    public container parmSalesOrderList(container _salesOrderList = salesOrderList)
    {
        salesOrderList = _salesOrderList;

        return salesOrderList;
    }

    /// <summary>
    /// parm method for csd sales order list container which contains sales order and OSCCode list
    /// </summary>
    /// <param name = "_csdSalesOrderList"> csd sales order list</param>
    /// <returns>csd sales order list</returns>
    [DataMemberAttribute, SysOperationControlVisibilityAttribute(false)]
    public container parmCSDSalesOrderList(container _csdSalesOrderList = csdSalesOrderList)
    {
        csdSalesOrderList = _csdSalesOrderList;

        return csdSalesOrderList;
    }

    /// <summary>
    /// Gets or sets the batch job ID.
    /// </summary>
    /// <param name="_batchJobId">The batch job ID to set.</param>
    /// <returns>The current batch job ID.</returns>
    [DataMemberAttribute, SysOperationControlVisibilityAttribute(false)]
    public RefRecId parmBatchJobId(RefRecId _batchJobId = batchJobId)
    {
        batchJobId = _batchJobId;

        return batchJobId;
    }

/// <summary>
/// Parm method to get/set can continue from staging lane flag, which indicates whether to consider conitinus use of customer staging position fetched from Warehouse.
/// </summary>
/// <param name = "_canContinueFromStagingLane">Boolean value</param>
/// <returns>Boolean true represents continuous use of staging lane, false to use exiting value from Warehouse's Customer starting position</returns>
[DataMemberAttribute, SysOperationControlVisibilityAttribute(false)]
public boolean parmContinueFromStagingLane(boolean _canContinueFromStagingLane = canContinueFromStagingLane)
{
    canContinueFromStagingLane = _canContinueFromStagingLane;
    return canContinueFromStagingLane;
}
